type LanguageContextValue={lang:Language;setLang:(language:Language)=>void;rtl:boolean;t:(key:string)=>string};
const LanguageContext=createContext<LanguageContextValue|null>(null);
export function LanguageProvider({children}:{children:ReactNode}){const[lang,setLangState]=useState<Language>("DE");useEffect(()=>{try{const saved=window.localStorage.getItem("nexora-language") as Language|null;if(saved&&supportedLanguages.includes(saved))setLangState(saved);else{const browser=(navigator.language||"de").slice(0,2).toUpperCase() as Language;if(supportedLanguages.includes(browser))setLangState(browser)}}catch{}},[]);const setLang=useCallback((next:Language)=>{setLangState(next);try{window.localStorage.setItem("nexora-language",next)}catch{}},[]);useEffect(()=>{document.documentElement.lang=lang.toLowerCase();document.documentElement.dir=lang==="AR"?"rtl":"ltr"},[lang]);const value=useMemo(()=>({lang,setLang,rtl:lang==="AR",t:(key:string)=>dictionaries[lang]?.[key]||sharedLabels[lang]?.[key]||commerceLabels[lang]?.[key]||deliveryLabels[lang]?.[key]||routeLabels[lang]?.[key]||homeMessages[lang]?.[key]||dictionaries.EN[key]||sharedLabels.EN[key]||commerceLabels.EN[key]||deliveryLabels.EN[key]||routeLabels.EN[key]||homeMessages.EN[key]||key}),[lang,setLang]);return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>}
export function useLanguage(){const context=useContext(LanguageContext);if(!context)throw new Error("useLanguage must be used within LanguageProvider");return context}
export function LanguageSwitcher({className=""}:{className?:string}){const{lang,setLang,t}=useLanguage();return <label className={"nexora-language-switcher "+className}><span className="sr-only">{t("language")}</span><select aria-label={t("language")} value={lang} onChange={e=>setLang(e.target.value as Language)}>{supportedLanguages.map(code=><option value={code} key={code}>{({DE:"Deutsch",EN:"English",FR:"Français",AR:"العربية",RU:"Русский",ZH:"中文",JA:"日本語",ES:"Español",IT:"Italiano",TR:"Türkçe"})[code]}</option>)}</select></label>}
